create table "book" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "edition" integer not null,
  "price" numeric(10, 2) not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  "store_id" bigint not null,
  constraint "book_pk" primary key ("id")
);

create table "book_store" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  constraint "book_store_pk" primary key ("id")
);

create table "author" (
  "id" bigint generated by default as identity not null,
  "name" text not null,
  "created_by" bigint null,
  "updated_by" bigint null,
  "created_at" timestamptz null default now(),
  "updated_at" timestamptz null default now(),
  "deleted_at" timestamptz null,
  constraint "author_pk" primary key ("id")
);

create table "book_author_mapping" (
  "book_id" bigint not null,
  "author_id" bigint not null,
  constraint "book_author_mapping_pk" primary key ("book_id", "author_id")
);

alter table "book" add constraint "book_fk_store_id" foreign key ("store_id") references "book_store" ("id");

alter table "book_author_mapping" add constraint "book_author_mapping_fk_book_id" foreign key ("book_id") references "book" ("id");

alter table "book_author_mapping" add constraint "book_author_mapping_fk_author_id" foreign key ("author_id") references "author" ("id");
